public class Solution {
    public int GetWinner(int[] arr, int k) {
        int maxElement = arr[0], count = 0;
        for (int i = 1; i < arr.Length; i++) {
            if (maxElement < arr[i]) {
                maxElement = arr[i];
                count = 1;
            } else {
                count++;
            }
            if (count == k) {
                break;
            }
        }
        return maxElement;
    }
}

class Solution(object):
    def getWinner(self, arr, k):
        """
        :type arr: List[int]
        :type k: int
        :rtype: int
        """
        max_arr = max(arr)
        cur_round = 0
        p = 1
        while True:
            if arr[0] == max_arr or cur_round == k:
                break
            if arr[0] > arr[p]:
                cur_round += 1
            else:
                cur_round = 1
                arr[0] = arr[p]
            p += 1
        return arr[0]
